    static std::string squashed(const std::string& text)
    {
        std::string result;
        bool        gap = false;
        for (const unsigned char c : text) {
            if (std::isspace(c)) {
                gap = !result.empty();
                continue;
            }
            if (gap) result += ' ';
            gap = false;
            result += static_cast<char>(c);
